import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import './addfrnds.scss';

const AddFrnds = () => {
  const { currentUser } = useContext(AuthContext);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchRecentUsers = async () => {
      setLoading(true);
      setError(null);
      const token = localStorage.getItem('token');
      if (!token) {
        setError('Please log in to view suggested friends.');
        setLoading(false);
        return;
      }

      try {
        console.log('Fetching from URL: http://localhost:5000/api/users/random');
        console.log('Token:', token);
        const res = await axios.get('http://localhost:5000/api/users/random', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        console.log('API response:', res.data);
        const filteredUsers = res.data.filter(user => user._id !== currentUser?.id);
        setUsers(filteredUsers);
        setError(null);
      } catch (err) {
        console.error('Error details:', err);
        console.error('Response:', err.response);
        const errorMessage = err.response?.data?.message || 'Failed to load suggested friends.';
        setError(errorMessage);
        setUsers([]);
      } finally {
        setLoading(false);
      }
    };

    if (currentUser) {
      fetchRecentUsers();
    }
  }, [currentUser]);

  const handleAddFriend = async (userId) => {
    try {
      const token = localStorage.getItem('token');
      const res = await axios.post(`http://localhost:5000/api/users/${userId}/friends`, {}, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      console.log('Friend added:', res.data);
      setUsers(users.filter((user) => user._id !== userId)); // Remove added friend from list
      alert('Friend added successfully!');
    } catch (err) {
      console.error('Error adding friend:', err);
      const errorMessage = err.response?.data?.message || 'Failed to add friend.';
      setError(errorMessage);
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('No profile picture provided, using default');
      return '/default-avatar.png';
    }
    const url = `http://localhost:5000${profilePicture}?t=${new Date().getTime()}`;
    console.log('Profile picture URL:', url);
    fetch(url)
      .then((res) => console.log('User image fetch status:', res.status, res.statusText))
      .catch((err) => console.error('User image fetch error:', err));
    return url;
  };

  if (!currentUser) {
    return <div className="add-frnds">Please log in to view suggested friends.</div>;
  }

  return (
    <div className="add-frnds">
      <h3>Suggested Friends</h3>
      {loading && <p className="loading">Loading...</p>}
      {error && <p className="error">{error}</p>}
      {users.length === 0 && !loading && !error && (
        <p className="no-users">No recently active users found.</p>
      )}
      <div className="users-list">
        {users.map((user) => (
          <div key={user._id} className="user-card">
            <div className="user-info">
              <img
                src={getProfilePictureUrl(user.profilePicture)}
                alt={`${user.username}'s profile`}
                className="avatar"
                onError={(e) => {
                  console.error(`Image load error for ${user.username}:`, e);
                  e.target.src = '/default-avatar.png';
                }}
              />
              <div className="details">
                <span className="username">{user.username}</span>
                <span className="name">{user.name}</span>
              </div>
            </div>
            <button
              className="add-btn"
              onClick={() => handleAddFriend(user._id)}
              title={`Add ${user.username} as a friend`}
              disabled={loading}
            >
              <PersonAddIcon />
              Add Friend
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AddFrnds;
